graphql.query:
query RefreshProduct($id: ID!, $variantsAfter: String) {
  product(id: $id) {
    id
    title
    handle
    descriptionHtml
    vendor
    productType
    tags
    status
    updatedAt
    media(first: 50) { nodes { ... on MediaImage { image { url } } } }
    variants(first: 250, after: $variantsAfter) {
      nodes {
        id
        sku
        title
        price
        compareAtPrice
        inventoryQuantity
        selectedOptions { name value }
        inventoryItem { id }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}

query BrowseProducts($after: String) {
  products(first: 10, after: $after, sortKey: CREATED_AT, reverse: true) {
    nodes {
      id
      title
      handle
      descriptionHtml
      vendor
      productType
      tags
      status
      updatedAt
      media(first: 10) { nodes { ... on MediaImage { image { url } } } }
      variants(first: 50) {
        nodes {
          id
          sku
          title
          price
          compareAtPrice
          inventoryQuantity
          selectedOptions { name value }
          inventoryItem { id }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

mutation StartProductBulkSync($query: String!) {
  bulkOperationRunQuery(query: $query) {
    bulkOperation { id status }
    userErrors { field message }
  }
}

graphql.variables:
{
  "query": "{ products { edges { node { id title handle descriptionHtml vendor productType tags status updatedAt media { edges { node { ... on MediaImage { image { url } } } } } variants { edges { node { id sku title price compareAtPrice inventoryQuantity selectedOptions { name value } inventoryItem { id } } } } } } } }"
}

graphql.query:
{
  currentBulkOperation(type: QUERY) {
    id
    status
    errorCode
    objectCount
    createdAt
    completedAt
    url
  }
}

query InventoryItemQuantity($id: ID!) {
  inventoryItem(id: $id) {
    variants(first: 1) { nodes { id inventoryQuantity } }
  }
}
